// Extract conversation data from webhook
const sessionId = $input.item.json.body.sessionId || `session-${Date.now()}`;
const userMessage = $input.item.json.body.message;
const userId = $input.item.json.body.userId || 'anonymous';
const channel = $input.item.json.body.channel || 'web'; // web, whatsapp, sms, voice

// Create structured input for memory retrieval
return {
  json: {
    sessionId: sessionId,
    userId: userId,
    userMessage: userMessage,
    channel: channel,
    timestamp: new Date().toISOString()
  }
};

// Build conversation history from memory
const currentMessage = $input.first().json.userMessage;
const sessionId = $input.first().json.sessionId;
const userId = $input.first().json.userId;
const channel = $input.first().json.channel;

// Get memory from previous node (if exists)
let conversationHistory = [];
try {
  // Redis GET returns data in 'reply' property in n8n
  const memoryData = $input.first().json.reply || $input.first().json.value;
  if (memoryData) {
    conversationHistory = JSON.parse(memoryData);
  }
} catch (error) {
  // No previous memory, start fresh
  conversationHistory = [];
}

// Add current message to history
conversationHistory.push({
  role: 'user',
  content: currentMessage,
  timestamp: new Date().toISOString()
});

// Keep only last 10 messages to manage token usage
if (conversationHistory.length > 10) {
  conversationHistory = conversationHistory.slice(-10);
}

return {
  json: {
    sessionId: sessionId,
    userId: userId,
    channel: channel,
    currentMessage: currentMessage,
    conversationHistory: conversationHistory
  }
};

// Check for emergency keywords
const message = $json.currentMessage.toLowerCase();
const emergencyKeywords = [
  'emergencia', 'urgente', 'no respira', 'convulsión', 'convulsion',
  'accidente', 'sangrado', 'inconsciente', 'desmayo', 'asfixia',
  'ahogo', 'muy grave', 'crisis', 'ataque'
];

const isEmergency = emergencyKeywords.some(keyword => message.includes(keyword));

return {
  json: {
    ...($json),
    isEmergency: isEmergency,
    requiresHumanEscalation: false // Will be determined by AI
  }
};

// Analyze AI response to determine if special actions needed
const aiResponse = $json.response?.content?.[0]?.text || $json.response?.text || '';
const conversationHistory = $input.first().json.conversationHistory;

// Check if response mentions appointments
const mentionsAppointment = /\b(cita|agendar|agenda|programar|reservar|appointment)\b/i.test(aiResponse);

// Check if response mentions pricing
const mentionsPricing = /\b(precio|costo|tarifa|cuanto cuesta|precio|pago|payment)\b/i.test(aiResponse);

// Check if collecting patient data
const collectingData = /\b(nombre|edad|teléfono|telefono|email|correo)\b/i.test(aiResponse);

// Add AI response to history
conversationHistory.push({
  role: 'assistant',
  content: aiResponse,
  timestamp: new Date().toISOString()
});

return {
  json: {
    sessionId: $input.first().json.sessionId,
    userId: $input.first().json.userId,
    channel: $input.first().json.channel,
    aiResponse: aiResponse,
    conversationHistory: conversationHistory,
    needsAppointmentCheck: mentionsAppointment,
    needsPricingCheck: mentionsPricing,
    collectingPatientData: collectingData,
    responseType: 'normal'
  }
};

